'use strict';
const $=s=>document.querySelector(s),fmt=n=>n.toLocaleString('en-US'),date=t=>new Date(t).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}),day=t=>new Date(t).toLocaleDateString('en-CA',{timeZone:'America/New_York'}),duration=s=>`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
let D,selected=182,view='runs',tab='live';
const milestones=[
{key:'jev-plans-v2',title:'Move from actions to plans',text:'The logs first record the plans-v2 planner on run 2. This marks an early transition to considering sequences of actions.',tag:'Planning',planner:true},
{key:'jev-review-v1',title:'Add a Jev review stage',text:'The first logged review-v1 decisions appear on run 4. Subsequent versions progressively added visible context and explicit mechanical checks.',tag:'Decision review'},
{key:'jev-visible-review-v9-endcheck',title:'A second look before ending the turn',text:'A triggered Jev review compares ending the turn with still-playable alternatives. All legal choices stay available.',tag:'Decision review'},
{key:'jev-visible-v11-block-refresh',title:'Trust fresh block values',text:'Re-observe after a block card under Unmovable, rather than reusing doubled values for later cards.',tag:'Forecast correction',planner:true},
{key:'jev-visible-review-v12-setup-dependencies',title:'Make setup earn its energy',text:'Expose visible exhaust setup and payoff dependencies, remaining energy, and the cost of drawing too late.',tag:'Sequence planning'},
{key:'jev-visible-v19-damage-caps',title:'Account for damage caps',text:'Apply explicit visible damage caps per hit, after Vulnerable. Large attacks no longer imply impossible kills.',tag:'Forecast correction',planner:true},
{key:'jev-visible-review-v15-reward-value',title:'Review card reward value',text:'Reward decisions gained explicit value checks. Later deck evidence work would make support requirements more concrete.',tag:'Deck building'},
{key:'jev-visible-v21-minion-departure',title:'Model minion departure',text:'Represent visible rules for enemies leaving after their leader is defeated, so the forecast can reflect that consequence.',tag:'Forecast correction',planner:true},
{key:'jev-visible-review-v19-deck-evidence',title:'Build around actual support',text:'Reward-only deck assessment adds conservative evidence for exhaust sources and asks Jev to identify the deck’s bottleneck.',tag:'Deck building'},
{key:'jev-visible-review-v21-facing-projection',title:'Plan the final facing',text:'For explicit opposing back-attack rules, compare the last targeted action and conservative incoming damage bounds.',tag:'Positioning'},
{key:'jev-visible-review-v22-deadline-extension',title:'Respect the lethal deadline',text:'Link visible countdowns to available extension cards; weigh affordability and reserve energy when no supported kill prevents death.',tag:'Survival'},
{key:'jev-visible-review-v23-target-focus',title:'Keep a primary target',text:'Ask Jev to concentrate major attacks across turns while distinguishing that plan from a cheap action to change facing.',tag:'Target choice'},
{key:'jev-visible-v23-retaliation',title:'Count the cost of attacking',text:'Model explicit single-hit, nonlethal retaliation. More complex timing remains unknown rather than falsely safe.',tag:'Forecast correction',planner:true},
{key:'jev-visible-review-v24-card-order',title:'Review card order',text:'One triggered Jev check compares setup-before-payoff sequences: Rage, Strength, Vulnerable and drawing before paid plays.',tag:'Sequence planning'}];
const offline=[
{title:'Jev network',tag:'Kept offline',text:'A compact network of Jev assessments did not beat the existing pipeline in the second batch: 16/20 versus 17/20 checks.',evidence:'September 22 · fixture checks, not match wins'},
{title:'Persistent plan + action benefit',tag:'Kept offline',text:'An opt-in plan and benefit layer scored 16/20 versus 17/20 for the baseline. Both passed 8/8 survivable checks.',evidence:'September 22 · controlled offline replay'},
{title:'Strength / cheap-attack preference',tag:'Kept offline',text:'Across 48 decisions, all 12 eligible paired comparisons kept the same choice. No demonstrated decision improvement.',evidence:'September 22 · saved rewards and controls'},
{title:'Make skipping a real alternative',tag:'Kept offline',text:'In 48 decisions, a marginal-value prompt skipped 3/24 rewards versus 0/24 for baseline. Better choices were not established.',evidence:'September 22 · reward replay'},
{title:'Rage-first sequence candidates',tag:'Kept offline',text:'Added 21 reordered plans across seven saved states. Jev selected none of the new plans in 48 replay decisions.',evidence:'September 22 · separate from the live card-order review'},
{title:'Survive until the next decision',tag:'Promising · offline',text:'On the recorded fatal state, both repeats switched from Bludgeon to Pommel Strike+; safe controls stayed unchanged. Opening setup choices did not improve.',evidence:'September 22 · 16 decisions; no proof of a saved fight'}];
function color(r){return r.win?'#89efb0':r.act===3?'#bfa2f5':r.act===2?'#ec8156':'#627490'}
function detail(){let r=D.runs[selected-1];$('#runOutput').value=selected;$('#runRange').value=selected;$('#detail').innerHTML=`<div class="tag">${r.win?'VERIFIED VICTORY':`ACT ${r.act} · FLOOR ${r.floor}`}</div><h3>Run ${r.n}<span style="color:${color(r)}">${r.win?' ✦':''}</span></h3><p>${date(r.start)} ET</p><dl><div><dt>Result</dt><dd>${r.win?'Victory':'Defeat'}</dd></div><div><dt>Highest floor</dt><dd>${r.floor}</dd></div><div><dt>Game duration</dt><dd>${duration(r.seconds)}</dd></div><div><dt>Decisions</dt><dd>${fmt(r.decisions)}</dd></div><div><dt>Jev input tokens</dt><dd>${fmt(r.inputTokens)}</dd></div><div><dt>Jev output tokens</dt><dd>${fmt(r.outputTokens)}</dd></div><div><dt>Total tokens</dt><dd>${fmt(r.totalTokens)}</dd></div><div><dt>Ascension</dt><dd>${r.ascension}</dd></div></dl><p>${r.win?'Final boss defeated. Rewards collected at 9 HP.':r.encounter}</p><p class="policy">${r.assisted?'Brief Luna adviser trial; Jev final choices.':'Jev 1.13.0'}<br>${r.reviews.at(-1)||r.policies.at(-1)||'Initial policy'}</p>`;$('#prev').disabled=selected===1;$('#next').disabled=selected===D.runs.length}
function chart(){const w=Math.max(320,$('#chart').clientWidth),h=$('#chart').clientHeight,L=32,R=12,T=36,B=30,iw=w-L-R,ih=h-T-B,y=f=>T+ih-f/50*ih;
let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${view==='runs'?'Highest floor for each of 182 runs.':'Average and highest floor by day.'}"><title>Jev run progress</title>`;
for(let [lo,hi,label] of [[0,17,'I'],[17,33,'II'],[33,50,'III']])svg+=`<rect x="${L}" y="${y(hi)}" width="${iw}" height="${y(lo)-y(hi)}" fill="${lo===33?'#252033':lo===17?'#261f1c':'#18202b'}" opacity=".5"/>`;
for(let f of [0,17,33,48])svg+=`<line x1="${L}" x2="${w-R}" y1="${y(f)}" y2="${y(f)}" stroke="#333b49" stroke-dasharray="3 4"/><text x="${L-8}" y="${y(f)+4}" text-anchor="end" fill="#a0a9b9" font-size="12">${f}</text>`;
if(view==='runs'){
 const step=iw/D.runs.length,x=n=>L+(n-.5)*step;
 for(let m of milestones){let pos=(m.planner?D.plannerVersions:D.reviewVersions)[m.key];m.run=pos.run;m.time=pos.time}
 // A small set of major chapter pins keeps the full timeline legible.
 const pins=[2,5,8,10,13].map(i=>milestones[i]);
 pins.forEach((m,i)=>{svg+=`<g class="pin" data-run="${m.run}" tabindex="0" role="button" aria-label="${m.title}, run ${m.run}"><line x1="${x(m.run)}" x2="${x(m.run)}" y1="26" y2="${h-B}" stroke="#758091" stroke-dasharray="2 5" opacity=".5"/><circle cx="${x(m.run)}" cy="16" r="10" fill="#293242"/><text x="${x(m.run)}" y="20" fill="white" font-size="12" text-anchor="middle">${i+1}</text><title>${m.title} · Run ${m.run}</title></g>`});
 D.runs.forEach(r=>{svg+=`<rect class="chartbar" data-run="${r.n}" x="${x(r.n)-step*.34}" y="${y(r.floor)}" width="${Math.max(1,step*.68)}" height="${y(0)-y(r.floor)}" fill="${color(r)}" opacity="${selected===r.n?1:.7}"><title>Run ${r.n} · Floor ${r.floor} · ${r.win?'Victory':r.encounter}</title></rect>`});
 const points=D.runs.map((r,i)=>{const a=D.runs.slice(Math.max(0,i-9),i+1);return `${x(r.n)},${y(a.reduce((s,r)=>s+r.floor,0)/a.length)}`}).join(' ');
 svg+=`<polyline points="${points}" fill="none" stroke="#edf2f8" stroke-width="1.5" pointer-events="none"/><line x1="${x(selected)}" x2="${x(selected)}" y1="${T}" y2="${h-B}" stroke="white" opacity=".7" pointer-events="none"/><circle cx="${x(selected)}" cy="${y(D.runs[selected-1].floor)}" r="4" fill="white" pointer-events="none"/>`;
 for(let n of [1,30,60,90,120,150,182])svg+=`<text x="${x(n)}" y="${h-5}" text-anchor="middle" fill="#a0a9b9" font-size="12">${n}</text>`;
 $('#chartHint').textContent='Pins: 1 End-turn review · 2 Damage caps · 3 Deck evidence · 4 Deadlines · 5 Card order';
}else{
 let groups=Object.entries(Object.groupBy(D.runs,r=>day(r.start))),step=iw/groups.length;
 groups.forEach(([d,rs],i)=>{let x=L+(i+.5)*step,avg=rs.reduce((s,r)=>s+r.floor,0)/rs.length,best=rs.reduce((a,b)=>a.floor>b.floor?a:b),bw=Math.min(step*.48,48);svg+=`<g class="chartbar" data-run="${best.n}"><rect x="${x-bw/2}" y="${y(avg)}" height="${y(0)-y(avg)}" width="${bw}" fill="${color(best)}" opacity=".85"/><line x1="${x}" x2="${x}" y1="${y(avg)}" y2="${y(best.floor)}" stroke="${color(best)}"/><circle cx="${x}" cy="${y(best.floor)}" r="4" fill="${color(best)}"/><text x="${x}" y="${y(best.floor)-9}" text-anchor="middle" fill="#ccd5e1" font-size="12">${rs.length} runs</text><text x="${x}" y="${h-5}" text-anchor="middle" fill="#a0a9b9" font-size="12">${new Date(rs[0].start).toLocaleDateString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric'})}</text><title>${d}: ${rs.length} runs; average floor ${avg.toFixed(1)}, best ${best.floor}</title></g>`});
 $('#chartHint').textContent='Bars show average floor; dots show highest floor. Select a day to inspect its deepest run.';
}
$('#chart').innerHTML=svg+'</svg>';$('#chart').querySelectorAll('[data-run]').forEach(el=>{el.onclick=()=>choose(+el.dataset.run);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(+el.dataset.run)}}})}
function choose(n){selected=Math.max(1,Math.min(D.runs.length,n));detail();chart()}
function renderMilestones(){if(tab==='lab'){$('#milestones').innerHTML=offline.map(m=>`<article class="milestone"><div class="meta"><span>${m.tag}</span><span class="badge">OFFLINE</span></div><h3>${m.title}</h3><p>${m.text}</p><div class="evidence">${m.evidence}</div></article>`).join('');return}
$('#milestones').innerHTML=milestones.map(m=>{const p=(m.planner?D.plannerVersions:D.reviewVersions)[m.key];return `<button class="milestone" data-run="${p.run}"><div class="meta"><span>RUN ${p.run}</span><span class="badge">${m.tag}</span></div><h3>${m.title}</h3><p>${m.text}</p><div class="evidence">First observed: ${date(p.time)} ET</div></button>`}).join('')+`<article class="milestone"><div class="meta"><span>SEP 22 · REPORT DATE</span><span class="badge">Reliability</span></div><h3>Smaller requests, same evidence</h3><p>Repeated card-order evidence was compacted to avoid request-size failures, preserving choices and warnings. This changed transport, not gameplay policy.</p><div class="evidence">Overnight report · 6:01 PM ET</div></article>`;
const extra=[{n:134,title:'A brief Luna adviser trial',text:'Luna Max reviewed two Jev proposals in the live run. Jev retained the final choice. The user stopped the slow experiment; baseline Jev resumed.',when:'Sep 21, 10:06 PM ET · first logged use',tag:'Stopped experiment'},{n:152,title:'Correct repeated-attack damage',text:'A narrow Replay forecast fix counted supported plain Strike repetitions and per-hit consequences. Verified against recorded transitions; not a general combat simulator.',when:'Sep 22, 8:19 AM ET · deployment report',tag:'Forecast correction'}];
extra.forEach(m=>{let el=document.createElement('button');el.className='milestone';el.dataset.run=m.n;el.innerHTML=`<div class="meta"><span>RUN ${m.n}</span><span class="badge">${m.tag}</span></div><h3>${m.title}</h3><p>${m.text}</p><div class="evidence">${m.when}</div>`;let before=[...$('#milestones').children].find(e=>Number(e.dataset.run)>m.n)||$('#milestones').lastElementChild;$('#milestones').insertBefore(el,before)});
$('#milestones').querySelectorAll('button').forEach(el=>el.onclick=()=>{view='runs';setPressed('allBtn','dailyBtn');choose(+el.dataset.run);$('.surface').scrollIntoView({behavior:'smooth',block:'start'})})}
function renderTokens(){
 const rows=[...D.runs],sort=$('#tokenSort').value;
 rows.sort(sort==='largest'?(a,b)=>b.inputTokens-a.inputTokens:(a,b)=>a.n-b.n);
 $('#tokenSummary').innerHTML=`<div><strong>${(D.totalInputTokens/1e6).toFixed(1)}M</strong><span>Recorded input tokens</span></div><div><strong>${(D.totalInputTokens/D.runs.length/1e6).toFixed(2)}M</strong><span>Average input / run</span></div><div><strong>${(D.totalOutputTokens/1e6).toFixed(2)}M</strong><span>Recorded output tokens</span></div><div><strong>${(D.runs.at(-1).inputTokens/1e6).toFixed(2)}M</strong><span>Winning run input</span></div>`;
 const max=Math.max(...rows.map(r=>r.inputTokens));
 $('#tokenRows').innerHTML=rows.map(r=>`<tr><td><button class="token-run" data-run="${r.n}">#${r.n}${r.win?' ✦':''}</button></td><td>Act ${r.act} · ${r.floor}</td><td class="token-value"><span class="token-bar" style="width:${r.inputTokens/max*100}%"></span><span>${fmt(r.inputTokens)}</span></td><td>${fmt(r.outputTokens)}</td><td>${fmt(r.totalTokens)}</td></tr>`).join('');
 $('#tokenRows').querySelectorAll('button').forEach(el=>el.onclick=()=>{choose(+el.dataset.run);$('.surface').scrollIntoView({behavior:'smooth'})});
 $('#tokenSort').onchange=renderTokens;
}
function setPressed(a,b){$('#'+a).setAttribute('aria-pressed','true');$('#'+b).setAttribute('aria-pressed','false')}
$('#allBtn').onclick=()=>{view='runs';setPressed('allBtn','dailyBtn');chart()};$('#dailyBtn').onclick=()=>{view='day';setPressed('dailyBtn','allBtn');chart()};$('#liveBtn').onclick=()=>{tab='live';setPressed('liveBtn','labBtn');renderMilestones()};$('#labBtn').onclick=()=>{tab='lab';setPressed('labBtn','liveBtn');renderMilestones()};$('#runRange').oninput=e=>choose(+e.target.value);$('#prev').onclick=()=>choose(selected-1);$('#next').onclick=()=>choose(selected+1);
fetch('data.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}).then(d=>{D=d;detail();chart();renderMilestones();renderTokens();new ResizeObserver(()=>chart()).observe($('#chart'))}).catch(()=>{$('#chart').textContent='The run archive could not be loaded. Please reload the page.'});
